<script setup>import { computed } from 'vue'const props = defineProps({  variant: { type: Object, required: false }})const details = computed(() => {  const metafields = props.variant?.metafields || []  const map = {}  metafields.forEach(mf => {    if (mf?.namespace && mf?.key) map[`${mf.namespace}_${mf.key}`] = mf.value  })  return {    name: map['custom_set_name'] || '',    composition: map['custom_composition'] || ''  }})</script><template>  <div      v-if="details.name || details.composition"      class="variant-meta"  >    <h4        v-if="details.name"        class="variant-meta__title"    >      {{ details.name }}    </h4>    <p        v-if="details.composition"        class="variant-meta__text"        v-html="details.composition.replace(/\n/g, '<br>')"    />  </div></template>